CREATE SCHEMA "analytics";
--> statement-breakpoint
CREATE VIEW "analytics"."v_ai_performance" AS (select "ai_decisions"."id" as "decision_id", "ai_decisions"."tenant_id" as "tenant_id", "ai_decisions"."case_id" as "case_id", "ai_decisions"."model" as "model", "ai_decisions"."status" as "decision_status", "ai_decisions"."latency_ms" as "latency_ms", "ai_decisions"."input_tokens" as "input_tokens", "ai_decisions"."output_tokens" as "output_tokens", "ai_decisions"."cost_minor_units" as "llm_cost_minor", "policy_evaluations"."id" as "evaluation_id", "policy_evaluations"."result" as "policy_result", "policy_evaluations"."latency_ms" as "policy_latency_ms", "ai_decisions"."created_at" as "decision_created_at" from "ai_decisions" left join "policy_evaluations" on "ai_decisions"."id" = "policy_evaluations"."decision_id");--> statement-breakpoint
CREATE VIEW "analytics"."v_funnel" AS (select "recovery_cases"."id" as "case_id", "recovery_cases"."tenant_id" as "tenant_id", "recovery_cases"."customer_id" as "customer_id", "recovery_cases"."risk_type" as "risk_type", "recovery_cases"."amount_at_risk" as "amount_at_risk", "recovery_cases"."currency" as "currency", "recovery_cases"."status" as "status", "recovery_cases"."opened_at" as "opened_at", "recovery_outcomes"."id" as "outcome_id", "recovery_outcomes"."recovered_amount" as "recovered_amount", "recovery_outcomes"."recovered_at" as "recovered_at" from "recovery_cases" left join "recovery_outcomes" on "recovery_cases"."id" = "recovery_outcomes"."case_id");--> statement-breakpoint
CREATE VIEW "analytics"."v_intervention_performance" AS (select "recovery_actions"."id" as "action_id", "recovery_actions"."tenant_id" as "tenant_id", "recovery_actions"."type" as "action_type", "recovery_actions"."case_id" as "case_id", "recovery_cases"."risk_type" as "risk_type", "recovery_cases"."amount_at_risk" as "amount_at_risk", "recovery_actions"."status" as "action_status", "recovery_actions"."completed_at" as "action_completed_at", "recovery_actions"."created_at" as "action_created_at", "recovery_outcomes"."id" as "outcome_id", "recovery_outcomes"."recovered_amount" as "recovered_amount", "recovery_outcomes"."recovery_cost" as "recovery_cost", "recovery_outcomes"."net_recovered" as "net_recovered", "recovery_outcomes"."recovered_at" as "recovered_at" from "recovery_actions" inner join "recovery_cases" on "recovery_actions"."case_id" = "recovery_cases"."id" left join "recovery_outcomes" on "recovery_cases"."id" = "recovery_outcomes"."case_id");--> statement-breakpoint
CREATE VIEW "analytics"."v_recovery_summary" AS (select "recovery_cases"."id" as "case_id", "recovery_cases"."tenant_id" as "tenant_id", "recovery_cases"."case_number" as "case_number", "recovery_cases"."customer_id" as "customer_id", "recovery_cases"."risk_type" as "risk_type", "recovery_cases"."amount_at_risk" as "amount_at_risk", "recovery_cases"."currency" as "currency", "recovery_cases"."status" as "status", "recovery_cases"."opened_at" as "opened_at", "recovery_cases"."closed_at" as "closed_at", "recovery_outcomes"."id" as "outcome_id", "recovery_outcomes"."payment_id" as "payment_id", "recovery_outcomes"."recovered_amount" as "recovered_amount", "recovery_outcomes"."recovery_cost" as "recovery_cost", "recovery_outcomes"."net_recovered" as "net_recovered", "recovery_outcomes"."attribution_method" as "attribution_method", "recovery_outcomes"."attribution_window_hours" as "attribution_window_hours", "recovery_outcomes"."recovered_at" as "recovered_at", "recovery_outcomes"."recorded_at" as "recorded_at" from "recovery_cases" left join "recovery_outcomes" on "recovery_cases"."id" = "recovery_outcomes"."case_id");--> statement-breakpoint
CREATE VIEW "analytics"."v_recovery_timeseries" AS (select "recovery_outcomes"."id" as "outcome_id", "recovery_outcomes"."tenant_id" as "tenant_id", "recovery_outcomes"."case_id" as "case_id", "recovery_outcomes"."payment_id" as "payment_id", "recovery_outcomes"."baseline_amount" as "baseline_amount", "recovery_outcomes"."recovered_amount" as "recovered_amount", "recovery_outcomes"."recovery_cost" as "recovery_cost", "recovery_outcomes"."net_recovered" as "net_recovered", "recovery_outcomes"."attribution_method" as "attribution_method", "recovery_outcomes"."attribution_window_hours" as "attribution_window_hours", "recovery_outcomes"."recovered_at" as "recovered_at", "recovery_outcomes"."recorded_at" as "recorded_at" from "recovery_outcomes");--> statement-breakpoint
CREATE VIEW "analytics"."v_risk_mix" AS (select "recovery_cases"."id" as "case_id", "recovery_cases"."tenant_id" as "tenant_id", "recovery_cases"."risk_type" as "risk_type", COALESCE("revenue_risks"."band"::text, CASE WHEN "recovery_cases"."risk_score" >= 70 THEN 'HIGH' WHEN "recovery_cases"."risk_score" >= 40 THEN 'MEDIUM' ELSE 'LOW' END) as "risk_band", "recovery_cases"."risk_score" as "risk_score", "recovery_cases"."amount_at_risk" as "amount_at_risk", "recovery_cases"."currency" as "currency", "recovery_cases"."status" as "status", "recovery_cases"."opened_at" as "opened_at", "recovery_outcomes"."id" as "outcome_id", "recovery_outcomes"."recovered_amount" as "recovered_amount" from "recovery_cases" left join "revenue_risks" on "recovery_cases"."risk_id" = "revenue_risks"."id" left join "recovery_outcomes" on "recovery_cases"."id" = "recovery_outcomes"."case_id");